const base = { execution_status: 'passed', validation: { unsupported_claims: 0, orphan_prd_elements: 0, orphan_delivery_items: 0 } };
const cases = [
  { test_id: 'POSITIVE-CONTROL', expected_route: 'release', evaluation_scores: { langfuse_code: true, llm_faithfulness: 1, llm_hallucination: 0 } },
  { test_id: 'NEG-MISSING-SCORE', expected_route: 'hold_for_human_review', evaluation_scores: { langfuse_code: true, llm_faithfulness: null, llm_hallucination: 0 } },
  { test_id: 'NEG-POLLING-TIMEOUT', expected_route: 'hold_for_human_review', evaluation_poll: { status: 'timeout', attempt: 6, max_attempts: 6 }, evaluation_scores: { langfuse_code: null, llm_faithfulness: null, llm_hallucination: null } },
  { test_id: 'NEG-HALLUCINATION', expected_route: 'hold_for_human_review', evaluation_scores: { langfuse_code: true, llm_faithfulness: 1, llm_hallucination: 0.25 } },
  { test_id: 'NEG-EVALUATOR-DISAGREEMENT', expected_route: 'hold_for_human_review', evaluation_scores: { langfuse_code: false, llm_faithfulness: 1, llm_hallucination: 0 } }
];
return cases.map(test => ({ json: { ...base, ...test } }));

const isPresent = value => value !== undefined && value !== null && value !== '';
const passLike = value => value === true || (typeof value === 'string' && ['pass','passed'].includes(value.toLowerCase())) || (Number.isFinite(Number(value)) && Number(value) >= 1);
return $input.all().map(item => {
  const x = item.json;
  const validation = x.validation ?? {};
  const unsupported = validation.unsupported_claims;
  const orphanChecks = Object.entries(validation).filter(([key]) => key.startsWith('orphan_'));
  const deterministicPresent = x.execution_status !== undefined && isPresent(unsupported);
  const deterministicPass = deterministicPresent && x.execution_status === 'passed' && Number(unsupported) === 0 && orphanChecks.every(([,value]) => Number(value) === 0);
  const codeRaw = x.evaluation_scores?.langfuse_code;
  const faithRaw = x.evaluation_scores?.llm_faithfulness;
  const hallucinationRaw = x.evaluation_scores?.llm_hallucination;
  const status = (present, passed) => present ? (passed ? 'pass' : 'fail') : 'missing';
  const layers = {
    deterministic_controls: { status: status(deterministicPresent, deterministicPass), observed: deterministicPass },
    langfuse_code: { status: status(isPresent(codeRaw), isPresent(codeRaw) && passLike(codeRaw)), observed: isPresent(codeRaw) ? codeRaw : null },
    llm_faithfulness: { status: status(isPresent(faithRaw), isPresent(faithRaw) && Number(faithRaw) >= 0.90), observed: isPresent(faithRaw) ? Number(faithRaw) : null },
    llm_hallucination: { status: status(isPresent(hallucinationRaw), isPresent(hallucinationRaw) && Number(hallucinationRaw) <= 0.10), observed: isPresent(hallucinationRaw) ? Number(hallucinationRaw) : null }
  };
  const entries = Object.entries(layers);
  const failed = entries.filter(([,layer]) => layer.status === 'fail').map(([name]) => name);
  const missing = entries.filter(([,layer]) => layer.status === 'missing').map(([name]) => name);
  const wouldRelease = entries.every(([,layer]) => layer.status === 'pass');
  return { json: { ...x, agreement_gate: { mode: 'enforced-test', thresholds: { faithfulness_min: 0.90, hallucination_max: 0.10 }, layers, score_completeness: missing.length ? 'incomplete' : 'complete', would_release: wouldRelease, decision: wouldRelease ? 'agreement' : (failed.length ? 'disagreement' : 'insufficient_evidence'), reasons: [...failed.map(n => `${n}:fail`), ...missing.map(n => `${n}:missing`)], release_action: wouldRelease ? 'release' : 'hold_for_human_review' }, production_loop: { enforcement_enabled: true, release_authorized: wouldRelease, release_blocked: !wouldRelease } } };
});

const results = $input.all().map(item => { const x = item.json; return { test_id: x.test_id, expected_route: x.expected_route, observed_route: x.observed_route, decision: x.agreement_gate?.decision, reasons: x.agreement_gate?.reasons ?? [], passed: x.expected_route === x.observed_route }; });
const failed = results.filter(result => !result.passed);
if (failed.length) throw new Error(`Negative-path assertion failure: ${JSON.stringify(failed)}`);
return [{ json: { suite: 'agreement-gate-negative-path-v0.1', status: 'passed', passed: results.length, failed: 0, results, verified_at: new Date().toISOString(), note: 'Local deterministic harness; no production calls or evaluator costs.' } }];
